fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. In the left sidebar, find the conversation named 'Scratch conversation (safe to delete)' — it is seeded for exactly this test — and open its '...' (more options) menu, then click 'Delete'. If that conversation is not present, use any other conversation EXCEPT 'Membership renewal questions' (another test depends on that one). Confirm the deletion if a confirmation prompt appears. Verify the conversation is removed from the sidebar list. If no conversations exist, first create one by sending a message, then delete it. The conversation disappearing from the list after confirmation is success. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
